119:      * section and every site appears exactly once.
120:      */
121:     private fun groupSites(sites: List<SiteRecord>): List<SiteRecord> {
122:         val pinnedLocalIds = appPrefs.pinnedSiteLocalIds
123:         val recentLocalIds = appPrefs.getRecentSiteLocalIds()
124:         val currentSiteId = activeSiteId.toLong()
