102:     fun getSection(section: Int): String = when (section) {
103:         PINNED_SECTION -> sectionTitle(R.string.site_picker_pinned_sites, PINNED_SECTION_TITLE)
104:         RECENT_SECTION -> sectionTitle(R.string.site_picker_recent_sites, RECENT_SECTION_TITLE)
105:         ALL_SECTIONS_SECTION -> sectionTitle(R.string.site_picker_all_sites, ALL_SECTIONS_SECTION_TITLE)
106:         else -> ""
107:     }
108: 
109:     private fun getSites(mode: SitePickerMode): List<SiteRecord> {
110:         val siteModels = when (mode) {
111:             SitePickerMode.WPCOM_SITES_ONLY -> siteStore.sitesAccessedViaWPComRest
112:             SitePickerMode.DEFAULT, SitePickerMode.SIMPLE -> siteStore.sites
113:         }
114:         return SiteRecordUtil.createRecords(siteModels)
115:     }
116: 
117:     /**
118:      * Groups the sites into the pinned, recent and remaining sections. A pinned site is never part of the recent
119:      * section and every site appears exactly once.
120:      */
121:     private fun groupSites(sites: List<SiteRecord>): List<SiteRecord> {
122:         val pinnedLocalIds = appPrefs.pinnedSiteLocalIds
123:         val recentLocalIds = appPrefs.getRecentSiteLocalIds()
124:         val currentSiteId = activeSiteId.toLong()
125: 
126:         val pinnedSites = sites.filter { it.localId in pinnedLocalIds }
127:         val recentSites = recentLocalIds
128:             .mapNotNull { localId -> sites.firstOrNull { it.localId == localId } }
129:             .filterNot { it.localId in pinnedLocalIds }
130:             .map { it.apply { recentPick = true } }
131:         val remainingSites = sites.filter { it.localId !in pinnedLocalIds && it.localId !in recentLocalIds }
132: 
133:         return buildList {
134:             addSection(PINNED_SECTION, SiteRecordUtil.sort(sortSites(pinnedSites), currentSiteId))
135:             addSection(RECENT_SECTION, recentSites)
136:             addSection(ALL_SECTIONS_SECTION, sortSites(remainingSites))
137:         }
138:     }
139: 
140:     private fun MutableList<SiteRecord>.addSection(section: Int, sites: List<SiteRecord>) {
141:         if (sites.isEmpty()) return
142:         add(sectionHeader(section))
143:         addAll(sites)
144:     }
145: 
146:     private fun sectionHeader(section: Int): SiteRecord = SiteRecord(
147:         SiteModel().apply {
148:             id = SiteRecordUtil.HEADER_LOCAL_ID
149:             name = getSection(section)
150:         }
151:     )
152: 
153:     private fun sortSites(sites: List<SiteRecord>): List<SiteRecord> =
154:         sites.sortedBy { it.blogNameOrHomeURL.lowercase() }
155: 
156:     @Suppress("SwallowedException")
157:     private fun sectionTitle(@StringRes titleId: Int, fallbackTitle: String): String = try {
158:         WordPress.instance.getString(titleId)
159:     } catch (error: RuntimeException) {
160:         fallbackTitle
161:     }
162: 
163:     /**
164:      * Live data is updated from the dispatcher the view model was created with, so the value is posted when the
165:      * current thread isn't the main one.
166:      */
167:     private fun <T> MutableLiveData<T>.updateValue(value: T) {
168:         val isMainThread = try {
169:             Looper.myLooper() == Looper.getMainLooper()
170:         } catch (error: RuntimeException) {
171:             true
172:         }
173:         if (isMainThread) setValue(value) else postValue(value)
174:     }
175: 
176:     companion object {
177:         private const val PINNED_SECTION = 0
178:         private const val RECENT_SECTION = 1
179:         private const val ALL_SECTIONS_SECTION = 2
180: 
181:         private const val PINNED_SECTION_TITLE = "Pinned sites"
182:         private const val RECENT_SECTION_TITLE = "Recent sites"
183:         private const val ALL_SECTIONS_SECTION_TITLE = "All sites"
184:     }
185: }

